diff --git a/estimator/dft_diagonals.go b/estimator/dft_diagonals.go
new file mode 100644
index 0000000..2ab6b5b
--- /dev/null
+++ b/estimator/dft_diagonals.go
@@ -0,0 +1,346 @@
+package estimator
+
+import (
+	"math"
+
+	"github.com/tuneinsight/lattigo/v6/circuits/ckks/dft"
+	"github.com/tuneinsight/lattigo/v6/schemes/ckks"
+	"github.com/tuneinsight/lattigo/v6/utils"
+)
+
+// DFTDiagonals is a factorized DFT matrix in double precision.
+type DFTDiagonals struct {
+	dft.MatrixLiteral
+	Value []map[int][]complex128
+}
+
+// NewDFTDiagonals generates the factorized DFT matrices of the literal in double precision
+// (same factorization as dft.MatrixLiteral.GenMatrices).
+func NewDFTDiagonals(d dft.MatrixLiteral, LogN int) (mat DFTDiagonals) {
+
+	mat.MatrixLiteral = d
+
+	logSlots := d.LogSlots
+	slots := 1 << logSlots
+	maxDepth := d.Depth(false)
+	ltType := d.Type
+	bitreversed := d.BitReversed
+	imagRepack := d.Format == dft.RepackImagAsReal
+
+	logdSlots := logSlots
+	if logdSlots < LogN-1 && imagRepack {
+		logdSlots++
+	}
+
+	roots := ckks.GetRootsComplex128(slots << 2)
+	pow5 := make([]int, (slots<<1)+1)
+	pow5[0] = 1
+	for i := 1; i < (slots<<1)+1; i++ {
+		pow5[i] = pow5[i-1] * 5
+		pow5[i] &= (slots << 2) - 1
+	}
+
+	var a, b, c [][]complex128
+	if ltType == dft.HomomorphicEncode {
+		a, b, c = ifftPlainVecF64(logSlots, 1<<logdSlots, roots, pow5)
+	} else {
+		a, b, c = fftPlainVecF64(logSlots, 1<<logdSlots, roots, pow5)
+	}
+
+	plainVector := make([]map[int][]complex128, maxDepth)
+
+	merge := make([]int, maxDepth)
+	fftLevel := logSlots
+	for i := 0; i < maxDepth; i++ {
+		depth := int(math.Ceil(float64(fftLevel) / float64(maxDepth-i)))
+		if ltType == dft.HomomorphicEncode {
+			merge[i] = depth
+		} else {
+			merge[len(merge)-i-1] = depth
+		}
+		fftLevel -= depth
+	}
+
+	fftLevel = logSlots
+	for i := 0; i < maxDepth; i++ {
+
+		if logSlots != logdSlots && ltType == dft.HomomorphicDecode && i == 0 && imagRepack {
+
+			plainVector[i] = genRepackMatrixF64(logSlots, bitreversed)
+			plainVector[i] = multiplyFFTMatrixWithNextFFTLevelF64(plainVector[i], logSlots, 2*slots, fftLevel, a[logSlots-fftLevel], b[logSlots-fftLevel], c[logSlots-fftLevel], ltType, bitreversed)
+
+			nextfftLevel := fftLevel - 1
+			for j := 0; j < merge[i]-1; j++ {
+				plainVector[i] = multiplyFFTMatrixWithNextFFTLevelF64(plainVector[i], logSlots, 2*slots, nextfftLevel, a[logSlots-nextfftLevel], b[logSlots-nextfftLevel], c[logSlots-nextfftLevel], ltType, bitreversed)
+				nextfftLevel--
+			}
+
+		} else {
+
+			plainVector[i] = genFFTDiagMatrixF64(logSlots, fftLevel, a[logSlots-fftLevel], b[logSlots-fftLevel], c[logSlots-fftLevel], ltType, bitreversed)
+
+			nextfftLevel := fftLevel - 1
+			for j := 0; j < merge[i]-1; j++ {
+				plainVector[i] = multiplyFFTMatrixWithNextFFTLevelF64(plainVector[i], logSlots, slots, nextfftLevel, a[logSlots-nextfftLevel], b[logSlots-nextfftLevel], c[logSlots-nextfftLevel], ltType, bitreversed)
+				nextfftLevel--
+			}
+		}
+
+		fftLevel -= merge[i]
+	}
+
+	if logSlots != logdSlots && ltType == dft.HomomorphicEncode && imagRepack {
+		for j := range plainVector[maxDepth-1] {
+			v := plainVector[maxDepth-1][j]
+			for x := 0; x < slots; x++ {
+				v[x+slots] = 0
+			}
+		}
+	}
+
+	scaling := 1.0
+	if d.Scaling != nil {
+		scaling, _ = d.Scaling.Float64()
+	}
+
+	if ltType == dft.HomomorphicEncode {
+		if d.Format == dft.RepackImagAsReal || d.Format == dft.SplitRealAndImag {
+			scaling /= float64(2 * slots)
+		} else {
+			scaling /= float64(slots)
+		}
+	}
+
+	scaling = math.Pow(scaling, 1/float64(d.Depth(false)))
+
+	for j := range plainVector {
+		for x := range plainVector[j] {
+			scaleSlice(plainVector[j][x], scaling)
+		}
+	}
+
+	mat.Value = plainVector
+
+	return
+}
+
+func fftPlainVecF64(logN, dslots int, roots []complex128, pow5 []int) (a, b, c [][]complex128) {
+
+	N := 1 << logN
+
+	a = make([][]complex128, logN)
+	b = make([][]complex128, logN)
+	c = make([][]complex128, logN)
+
+	size := 1
+	if 2*N == dslots {
+		size = 2
+	}
+
+	index := 0
+	for m := 2; m <= N; m <<= 1 {
+
+		aM := make([]complex128, dslots)
+		bM := make([]complex128, dslots)
+		cM := make([]complex128, dslots)
+
+		tt := m >> 1
+
+		for i := 0; i < N; i += m {
+
+			gap := N / m
+			mask := (m << 2) - 1
+
+			for j := 0; j < m>>1; j++ {
+
+				k := (pow5[j] & mask) * gap
+
+				idx1 := i + j
+				idx2 := i + j + tt
+
+				for u := 0; u < size; u++ {
+					aM[idx1+u*N] = roots[0]
+					aM[idx2+u*N] = -roots[k]
+					bM[idx1+u*N] = roots[k]
+					cM[idx2+u*N] = roots[0]
+				}
+			}
+		}
+
+		a[index] = aM
+		b[index] = bM
+		c[index] = cM
+
+		index++
+	}
+
+	return
+}
+
+func ifftPlainVecF64(logN, dslots int, roots []complex128, pow5 []int) (a, b, c [][]complex128) {
+
+	N := 1 << logN
+
+	a = make([][]complex128, logN)
+	b = make([][]complex128, logN)
+	c = make([][]complex128, logN)
+
+	size := 1
+	if 2*N == dslots {
+		size = 2
+	}
+
+	index := 0
+	for m := N; m >= 2; m >>= 1 {
+
+		aM := make([]complex128, dslots)
+		bM := make([]complex128, dslots)
+		cM := make([]complex128, dslots)
+
+		tt := m >> 1
+
+		for i := 0; i < N; i += m {
+
+			gap := N / m
+			mask := (m << 2) - 1
+
+			for j := 0; j < m>>1; j++ {
+
+				k := ((m << 2) - (pow5[j] & mask)) * gap
+
+				idx1 := i + j
