+func genFFTDiagMatrixF64(logL, fftLevel int, a, b, c []complex128, ltType dft.Type, bitreversed bool) (vectors map[int][]complex128) {
+
+	var rot int
+
+	if ltType == dft.HomomorphicEncode && !bitreversed || ltType == dft.HomomorphicDecode && bitreversed {
+		rot = 1 << (fftLevel - 1)
+	} else {
+		rot = 1 << (logL - fftLevel)
+	}
+
+	vectors = make(map[int][]complex128)
+
+	if bitreversed {
+		utils.BitReverseInPlaceSlice(a, 1<<logL)
+		utils.BitReverseInPlaceSlice(b, 1<<logL)
+		utils.BitReverseInPlaceSlice(c, 1<<logL)
+
+		if len(a) > 1<<logL {
+			utils.BitReverseInPlaceSlice(a[1<<logL:], 1<<logL)
+			utils.BitReverseInPlaceSlice(b[1<<logL:], 1<<logL)
+			utils.BitReverseInPlaceSlice(c[1<<logL:], 1<<logL)
+		}
+	}
+
+	addToDiagMatrixF64(vectors, 0, a)
+	addToDiagMatrixF64(vectors, rot, b)
+	addToDiagMatrixF64(vectors, (1<<logL)-rot, c)
+
+	return
+}
+
+func genRepackMatrixF64(logL int, bitreversed bool) (vectors map[int][]complex128) {
+
+	vectors = make(map[int][]complex128)
+
+	a := make([]complex128, 2<<logL)
+	b := make([]complex128, 2<<logL)
+
+	for i := 0; i < 1<<logL; i++ {
+		a[i] = 1
+		a[i+(1<<logL)] = 1i
+		b[i] = 1i
+		b[i+(1<<logL)] = 1
+	}
+
+	addToDiagMatrixF64(vectors, 0, a)
+	addToDiagMatrixF64(vectors, (1 << logL), b)
+
+	return
+}
+
+func multiplyFFTMatrixWithNextFFTLevelF64(vec map[int][]complex128, logL, N, nextLevel int, a, b, c []complex128, ltType dft.Type, bitreversed bool) (newVec map[int][]complex128) {
+
+	var rot int
+
+	newVec = make(map[int][]complex128)
+
+	if ltType == dft.HomomorphicEncode && !bitreversed || ltType == dft.HomomorphicDecode && bitreversed {
+		rot = (1 << (nextLevel - 1)) & (N - 1)
+	} else {
+		rot = (1 << (logL - nextLevel)) & (N - 1)
+	}
+
+	if bitreversed {
+		utils.BitReverseInPlaceSlice(a, 1<<logL)
+		utils.BitReverseInPlaceSlice(b, 1<<logL)
+		utils.BitReverseInPlaceSlice(c, 1<<logL)
+
+		if len(a) > 1<<logL {
+			utils.BitReverseInPlaceSlice(a[1<<logL:], 1<<logL)
+			utils.BitReverseInPlaceSlice(b[1<<logL:], 1<<logL)
+			utils.BitReverseInPlaceSlice(c[1<<logL:], 1<<logL)
+		}
+	}
+
+	for _, i := range utils.GetSortedKeys(vec) {
+		addToDiagMatrixF64(newVec, i, rotateAndMulNewF64(vec[i], 0, a))
+		addToDiagMatrixF64(newVec, (i+rot)&(N-1), rotateAndMulNewF64(vec[i], rot, b))
+		addToDiagMatrixF64(newVec, (i-rot)&(N-1), rotateAndMulNewF64(vec[i], -rot, c))
+	}
+
+	return
+}
+
+func addToDiagMatrixF64(diagMat map[int][]complex128, index int, vec []complex128) {
+	if diagMat[index] == nil {
+		diagMat[index] = append([]complex128(nil), vec...)
+	} else {
+		d := diagMat[index]
+		for i := range d {
+			d[i] += vec[i]
+		}
+	}
+}
+
+func rotateAndMulNewF64(a []complex128, k int, b []complex128) (c []complex128) {
+	c = make([]complex128, len(a))
+	mask := len(a) - 1
+	for i := range c {
+		c[i] = b[i] * a[(i+k)&mask]
+	}
+	return
+}
+
+// CoeffsToSlotsDiagonalsNew applies the homomorphic encoding with double precision matrices.
+func (e Estimator) CoeffsToSlotsDiagonalsNew(el *Element, mat DFTDiagonals) (elReal, elImag *Element, err error) {
+	return e.coeffsToSlotsNew(el, mat.MatrixLiteral, mat.Value)
+}
+
+// SlotsToCoeffsDiagonalsNew applies the homomorphic decoding with double precision matrices.
+func (e Estimator) SlotsToCoeffsDiagonalsNew(elReal, elImag *Element, mat DFTDiagonals) (el *Element, err error) {
+	el = e.newElement(1, elReal.Level, elReal.Scale)
+	return el, e.slotsToCoeffs(elReal, elImag, mat.MatrixLiteral, mat.Value, el)
+}
