+	var va, vs float64
+	for r := 0; r < R; r++ {
+		va += (avg[r] - ma) * (avg[r] - ma)
+		vs += (std[r] - ms) * (std[r] - ms)
+	}
+	va = max(va/float64(R), 1e-12)
+	vs = max(vs/float64(R), 1e-12)
