+	best, bestD := 0, math.Inf(1)
+	for r := 0; r < R; r++ {
+		d := (avg[r]-ma)*(avg[r]-ma)/va + (std[r]-ms)*(std[r]-ms)/vs
+		if d < bestD {
+			best, bestD = r, d
+		}
+	}
+
+	return best
